// ═══════════════════════════════════════════════════════════════
// Abstract Factory — full worked example: UI Theme System
// ═══════════════════════════════════════════════════════════════

// ── Abstract Products ────────────────────────────────────────────
class Button {
  render()  { throw new Error('Button.render() not implemented'); }
  getLabel(){ throw new Error('Button.getLabel() not implemented'); }
}

class Input {
  render()   { throw new Error('Input.render() not implemented'); }
  getValue() { throw new Error('Input.getValue() not implemented'); }
}

class Card {
  render(content) { throw new Error('Card.render() not implemented'); }
}

// ── Concrete Products: Light Theme ───────────────────────────────
class LightButton extends Button {
  render()   { return '<button class="btn-light">Submit</button>'; }
  getLabel() { return 'Submit'; }
}

class LightInput extends Input {
  render()   { return '<input class="input-light" placeholder="Type here..." />'; }
  getValue() { return '(light input value)'; }
}

class LightCard extends Card {
  render(content) {
    return `<div class="card-light" style="background:#fff;border:1px solid #e2e8f0">${content}</div>`;
  }
}

// ── Concrete Products: Dark Theme ────────────────────────────────
class DarkButton extends Button {
  render()   { return '<button class="btn-dark">Submit</button>'; }
  getLabel() { return 'Submit'; }
}

class DarkInput extends Input {
  render()   { return '<input class="input-dark" placeholder="Type here..." />'; }
  getValue() { return '(dark input value)'; }
}

class DarkCard extends Card {
  render(content) {
    return `<div class="card-dark" style="background:#1a1a2e;border:1px solid #4a4a8a">${content}</div>`;
  }
}

// ── Concrete Products: High Contrast Theme ────────────────────────
class HCButton extends Button {
  render()   { return '<button class="btn-hc" style="background:#000;color:#ff0;border:3px solid #ff0">Submit</button>'; }
  getLabel() { return 'Submit'; }
}

class HCInput extends Input {
  render()   { return '<input class="input-hc" style="background:#000;color:#ff0;border:3px solid #ff0" />'; }
  getValue() { return '(high-contrast input value)'; }
}

class HCCard extends Card {
  render(content) {
    return `<div class="card-hc" style="background:#000;border:3px solid #ff0">${content}</div>`;
  }
}

// ── Abstract Factory ─────────────────────────────────────────────
class ThemeFactory {
  createButton() { throw new Error('createButton() not implemented'); }
  createInput()  { throw new Error('createInput() not implemented'); }
  createCard()   { throw new Error('createCard() not implemented'); }
}

// ── Concrete Factories ───────────────────────────────────────────
class LightThemeFactory extends ThemeFactory {
  createButton() { return new LightButton(); }
  createInput()  { return new LightInput(); }
  createCard()   { return new LightCard(); }
}

class DarkThemeFactory extends ThemeFactory {
  createButton() { return new DarkButton(); }
  createInput()  { return new DarkInput(); }
  createCard()   { return new DarkCard(); }
}

// Adding a new FAMILY = one new factory + three new product classes.
// Zero changes to client code, AbstractFactory, or existing families.
class HighContrastThemeFactory extends ThemeFactory {
  createButton() { return new HCButton(); }
  createInput()  { return new HCInput(); }
  createCard()   { return new HCCard(); }
}

// ── Client: LoginForm ────────────────────────────────────────────
// Only knows ThemeFactory, Button, Input, Card — zero concrete types.
class LoginForm {
  #button;
  #input;
  #card;

  constructor(factory) {
    // All products from one factory = guaranteed consistency
    this.#button = factory.createButton();
    this.#input  = factory.createInput();
    this.#card   = factory.createCard();
  }

  render() {
    const inner = [this.#input.render(), this.#button.render()].join('\n  ');
    return this.#card.render(inner);
  }

  submit() {
    const value = this.#input.getValue();
    return `Submitting: ${value} via ${this.#button.getLabel()}`;
  }
}

// ── Factory Registry ─────────────────────────────────────────────
const FACTORIES = {
  light:        new LightThemeFactory(),
  dark:         new DarkThemeFactory(),
  highContrast: new HighContrastThemeFactory(),
};

function getThemeFactory(theme) {
  const factory = FACTORIES[theme];
  if (!factory) throw new Error(`Unknown theme: '${theme}'. Available: ${Object.keys(FACTORIES).join(', ')}`);
  return factory;
}

// ── Usage ─────────────────────────────────────────────────────────
const themes = ['light', 'dark', 'highContrast'];
for (const theme of themes) {
  const form = new LoginForm(getThemeFactory(theme));
  console.log(`\n=== ${theme} ===${form.render()}`);
  console.log(form.submit());
}

// LoginForm never had to change when HighContrast was added.
// Cross-family mixing (LightButton + DarkCard) is impossible by construction.

// ═══════════════════════════════════════════════════════════════
// Abstract Factory in TypeScript — database adapter layer
// ═══════════════════════════════════════════════════════════════

// ── Abstract Products ────────────────────────────────────────────
interface QueryBuilder {
  select(table: string, columns: string[]): string;
  insert(table: string, data: Record<string, unknown>): string;
  limit(n: number): string;
}

interface ConnectionPool {
  connect(config: DbConfig): Promise<void>;
  disconnect(): Promise<void>;
  getStats(): { active: number; idle: number };
}

interface MigrationRunner {
  run(migrations: Migration[]): Promise<void>;
  rollback(steps: number): Promise<void>;
  status(): Promise<string[]>;
}

// Supporting types
interface DbConfig { host: string; port: number; database: string; }
interface Migration { name: string; up: string; down: string; }

// ── Abstract Factory ─────────────────────────────────────────────
interface DatabaseAdapterFactory {
  createQueryBuilder(): QueryBuilder;
  createConnectionPool(): ConnectionPool;
  createMigrationRunner(): MigrationRunner;
}

// ── Concrete Products: PostgreSQL family ─────────────────────────
class PgQueryBuilder implements QueryBuilder {
  select(table: string, columns: string[]): string {
    return `SELECT ${columns.join(', ')} FROM "${table}"`;
  }
  insert(table: string, data: Record<string, unknown>): string {
    const cols = Object.keys(data).map(k => `"${k}"`).join(', ');
    const vals = Object.values(data).map(v => `$${v}`).join(', ');
    return `INSERT INTO "${table}" (${cols}) VALUES (${vals}) RETURNING *`;
  }
  limit(n: number): string { return `LIMIT ${n}`; }
}

class PgConnectionPool implements ConnectionPool {
  async connect(cfg: DbConfig) { console.log(`PG: connecting to ${cfg.host}:${cfg.port}/${cfg.database}`); }
  async disconnect() { console.log('PG: pool disconnected'); }
  getStats() { return { active: 3, idle: 7 }; }
}

class PgMigrationRunner implements MigrationRunner {
  async run(ms: Migration[]) { console.log(`PG: running ${ms.length} migrations`); }
  async rollback(steps: number) { console.log(`PG: rolling back ${steps} steps`); }
  async status() { return ['001_initial done', '002_add_users done']; }
}

// ── Concrete Products: SQLite family (e.g. for tests / dev) ───────
class SqliteQueryBuilder implements QueryBuilder {
  select(table: string, columns: string[]): string {
    return `SELECT ${columns.join(', ')} FROM \`${table}\``;
  }
  insert(table: string, data: Record<string, unknown>): string {
    const cols = Object.keys(data).map(k => `\`${k}\``).join(', ');
    const vals = Object.values(data).map(v => `'${v}'`).join(', ');
    return `INSERT INTO \`${table}\` (${cols}) VALUES (${vals})`;
  }
  limit(n: number): string { return `LIMIT ${n}`; }
}

class SqliteConnectionPool implements ConnectionPool {
  async connect(cfg: DbConfig) { console.log(`SQLite: opening ${cfg.database}.db`); }
  async disconnect() { console.log('SQLite: file closed'); }
  getStats() { return { active: 1, idle: 0 }; }
}

class SqliteMigrationRunner implements MigrationRunner {
  async run(ms: Migration[]) { console.log(`SQLite: running ${ms.length} migrations in-memory`); }
  async rollback(steps: number) { console.log(`SQLite: rollback ${steps} steps`); }
  async status() { return ['001_initial done']; }
}

// ── Concrete Factories ───────────────────────────────────────────
class PostgresAdapterFactory implements DatabaseAdapterFactory {
  createQueryBuilder(): QueryBuilder  { return new PgQueryBuilder(); }
  createConnectionPool(): ConnectionPool { return new PgConnectionPool(); }
  createMigrationRunner(): MigrationRunner { return new PgMigrationRunner(); }
}

class SqliteAdapterFactory implements DatabaseAdapterFactory {
  createQueryBuilder(): QueryBuilder  { return new SqliteQueryBuilder(); }
  createConnectionPool(): ConnectionPool { return new SqliteConnectionPool(); }
  createMigrationRunner(): MigrationRunner { return new SqliteMigrationRunner(); }
}

// ── Client: Repository uses only abstract types ───────────────────
class UserRepository {
  private qb: QueryBuilder;
  private pool: ConnectionPool;

  constructor(factory: DatabaseAdapterFactory, private config: DbConfig) {
    this.qb   = factory.createQueryBuilder();
    this.pool = factory.createConnectionPool();
  }

  async init() { await this.pool.connect(this.config); }
  async cleanup() { await this.pool.disconnect(); }

  findAll(): string {
    const query = this.qb.select('users', ['id', 'email', 'created_at']);
    const limited = `${query} ${this.qb.limit(50)}`;
    return limited;
  }

  insertUser(email: string): string {
    return this.qb.insert('users', { email, created_at: new Date().toISOString() });
  }
}

// ── Usage: production vs. test ───────────────────────────────────
const prodConfig: DbConfig = { host: 'db.prod.example.com', port: 5432, database: 'app' };
const testConfig: DbConfig = { host: 'localhost', port: 0, database: ':memory:' };

// In production — inject Postgres factory
const prodRepo = new UserRepository(new PostgresAdapterFactory(), prodConfig);
console.log('Production query:', prodRepo.findAll());
// → SELECT id, email, created_at FROM "users" LIMIT 50

// In tests — inject SQLite factory; UserRepository code unchanged
const testRepo = new UserRepository(new SqliteAdapterFactory(), testConfig);
console.log('Test query:', testRepo.findAll());
// → SELECT id, email, created_at FROM `users` LIMIT 50

// The TypeScript compiler would error if SqliteAdapterFactory
// forgot to implement createMigrationRunner() — compile-time safety.
